125	const PROFILE_PHASES = ['parse', 'prepare', 'measure', 'layout', 'paint', 'serialize'] as const;
126	
127	// One render's normalized per-phase durations + total.
128	type RunSample = { total: number; phases: Record<string, number> };
129	// Trimmed-mean aggregate for one (diagram, layout) series.
