144	function findSpan(tree: ProfileSpanLike, name: string): ProfileSpanLike | undefined {
145	  if (tree.name === name) return tree;
146	  for (const child of tree.children) {
147	    const found = findSpan(child, name);
148	    if (found) return found;
149	  }
150	  return undefined;
151	}
152	
153	// Resolve a phase's duration from a render tree, normalizing the measure/layout
154	// split so the columns are comparable across layouts. elk measures DOM node
155	// sizes in its measureLayout hook (the top-level "measure" span) and its layout
156	// span is pure algorithm. dagre instead supplies a no-op measure hook and sizes
157	// nodes inside its layout core, emitting a "measure" span nested in "layout". So:
158	//   measure = the hook span + any measure span nested inside layout
159	//   layout  = the layout span minus that nested measure (i.e. pure algorithm)
160	// Other phases are read directly.
161	function phaseDuration(tree: ProfileSpanLike, phase: string): number | undefined {
162	  if (phase === 'measure') {
163	    const hook = findSpan(tree, 'measure');
164	    const layoutSpan = findSpan(tree, 'layout');
165	    const inLayout = layoutSpan ? findSpan(layoutSpan, 'measure') : undefined;
166	    if (!hook && !inLayout) return undefined;
167	    return (hook?.duration ?? 0) + (inLayout && inLayout !== hook ? inLayout.duration : 0);
168	  }
169	  if (phase === 'layout') {
170	    const layoutSpan = findSpan(tree, 'layout');
171	    if (!layoutSpan) return undefined;
172	    const inLayout = findSpan(layoutSpan, 'measure');
173	    return layoutSpan.duration - (inLayout?.duration ?? 0);
174	  }
175	  return findSpan(tree, phase)?.duration;
176	}
