178	// Time of the actual external library call (dagreLayout / elk.layout), captured
179	// as a "layoutCore" span inside the layout phase. The rest of "layout" is our
180	// own wrapper code (the part we can actually optimize).
181	function layoutLibDuration(tree: ProfileSpanLike): number | undefined {
182	  const layoutSpan = findSpan(tree, 'layout');
183	  if (!layoutSpan) return undefined;
184	  // The top-level external call is a DIRECT child of the layout span. dagre also
185	  // emits nested layoutCore spans for subgraphs (deeper, inside the measure
186	  // span); a depth-first search would wrongly grab one of those, so only look one
187	  // level down. (Nested subgraph layout time still lands in `measure` — the
188	  // documented recursion caveat.)
189	  return layoutSpan.children.find((c) => c.name === 'layoutCore')?.duration;
190	}
