196	// Normalize one render tree (+ flat buckets) to its per-phase durations + total.
197	function sampleFromTree(tree: ProfileSpanLike, buckets: Record<string, number> = {}): RunSample {
198	  const phases: Record<string, number> = {};
199	  for (const phase of PROFILE_PHASES) {
200	    const d = phaseDuration(tree, phase);
201	    if (typeof d === 'number') phases[phase] = d;
202	  }
203	  // Split the layout phase into the external library call vs. our wrapper.
204	  const lib = layoutLibDuration(tree);
205	  if (typeof lib === 'number') {
206	    phases.layoutLib = lib;
207	    if (typeof phases.layout === 'number') {
208	      phases.layoutOurs = Math.max(0, phases.layout - lib);
209	    }
210	  }
211	  // Flat accumulators summed across the render (e.g. getBBox, getBoundingClientRect).
212	  for (const [name, value] of Object.entries(buckets)) {
213	    if (typeof value === 'number') phases[name] = value;
214	  }
215	  return { total: tree.duration, phases };
216	}
