220	function trimmedStats(samples: RunSample[]): RunStats | null {
221	  if (samples.length === 0) return null;
222	  let kept = samples;
223	  if (samples.length >= 3) {
224	    kept = [...samples].sort((a, b) => a.total - b.total).slice(1, -1);
225	  }
226	  const phases: Record<string, number> = {};
227	  // Aggregate every key any sample carries (phases + dynamic buckets like getBBox).
228	  const keys = new Set<string>();
229	  for (const s of kept) {
230	    for (const k of Object.keys(s.phases)) keys.add(k);
231	  }
232	  for (const phase of keys) {
233	    const vals = kept.map((k) => k.phases[phase]).filter((v): v is number => typeof v === 'number');
234	    if (vals.length) {
235	      phases[phase] = mean(vals);
236	    }
237	  }
238	  return { total: mean(kept.map((k) => k.total)), phases, samples: kept.length };
