680	    // Mermaid uses its own logger which routes to console.info/debug/warn/error.
681	    // Capture those too (map debug/info/log -> panel "info").
682	    console.log = (...args) => {
683	      capture('info', args);
684	      this.#originalConsole!.log.apply(console, args as any);
685	    };
686	    console.info = (...args) => {
687	      capture('info', args);
688	      this.#originalConsole!.info.apply(console, args as any);
689	    };
690	    console.debug = (...args) => {
691	      capture('info', args);
