768	  async #saveSizes() {
769	    if (!this.filePath || this.sizesSaving) return;
770	
771	    const unavailableReason = sizeCaptureUnavailableReason(this.layout);
772	    if (unavailableReason) {
773	      this.sizesMessage = 'size data unavailable';
774	      this.error = unavailableReason;
775	      return;
776	    }
777	
778	    this.sizesSaving = true;
779	    this.error = '';
780	    this.sizesMessage = this.dirty ? 'saving diagram...' : 'capturing sizes...';
781	
782	    const previousCaptureFlag = Boolean(window.mermaidCaptureSizes);
783	    const previousLastCapture = window.mermaidLastCapturedSizes;
784	
785	    try {
786	      if (this.dirty) {
787	        const saved = await this.#saveSource();
788	        if (!saved) {
789	          this.sizesMessage = 'save diagram failed';
790	          return;
791	        }
792	      }
793	
794	      window.mermaidLastCapturedSizes = undefined;
795	      window.mermaidCaptureSizes = true;
796	      this.sizesMessage = 'capturing sizes...';
797	
798	      const rendered = await this.#renderCurrentSource();
799	      if (!rendered) {
800	        throw new Error(this.error || 'Could not render diagram for size capture');
801	      }
802	
803	      const captured = window.mermaidLastCapturedSizes;
804	      const nodes = captured?.sizes.nodes ?? [];
805	      if (nodes.length === 0) {
806	        throw new Error('Mermaid did not capture any node sizes; select a capture-enabled layout');
807	      }
808	
809	      this.sizesMessage = 'saving sizes...';
810	      const res = await fetch('/dev/api/sizes', {
811	        method: 'POST',
812	        headers: { 'Content-Type': 'application/json' },
813	        body: JSON.stringify({
814	          path: this.filePath,
815	          nodes,
816	          capturedFrom: `dev-explorer ${this.filePath} theme=${this.theme} look=${this.look} layout=${this.layout}`,
817	        }),
818	      });
819	      if (!res.ok) {
820	        const message = await res.text();
821	        throw new Error(message || `HTTP ${res.status}`);
822	      }
823	
824	      const json = (await res.json()) as { path?: string; nodes?: number };
825	      this.sizesMessage = `sizes saved${json.nodes ? ` (${json.nodes})` : ''}`;
826	    } catch (e) {
827	      this.error = e instanceof Error ? e.message : String(e);
828	      this.sizesMessage = 'size save failed';
829	    } finally {
830	      window.mermaidCaptureSizes = previousCaptureFlag;
831	      if (!window.mermaidLastCapturedSizes) {
832	        window.mermaidLastCapturedSizes = previousLastCapture;
833	      }
834	      this.sizesSaving = false;
835	    }
836	  }
