981	  // Resolve the set of diagrams to profile: just the current file, or every
982	  // sibling .mmd in the current folder. Sources are fetched up front so a slow
983	  // fetch never lands inside a timed render.
984	  async #resolveProfileDiagrams(): Promise<{ path: string; source: string }[]> {
985	    if (this.profileScope === 'folder') {
986	      const paths = this.siblings.length ? this.siblings : this.filePath ? [this.filePath] : [];
987	      const diagrams: { path: string; source: string }[] = [];
988	      for (const path of paths) {
989	        try {
990	          diagrams.push({ path, source: await this.#fetchSourceFor(path) });
991	        } catch {
992	          // Skip unreadable files rather than aborting the whole run.
993	        }
994	      }
995	      return diagrams;
996	    }
997	    return this.source ? [{ path: this.filePath || '(current)', source: this.source }] : [];
998	  }
