1000	  /**
1001	   * Benchmark the selected diagram set across the selected layouts and produce a
1002	   * per-layout score (total render time, lower is better) so improvements are
1003	   * trackable run-to-run.
1004	   *
1005	   * Renders run sequentially (the profiler has a single phase stack and parallel
1006	   * renders would contend on the main thread). Each layout is warmed up once
1007	   * (untimed) to absorb the one-time dynamic layout-loader import, and each
1008	   * (diagram, layout) series drops its fastest and slowest run before averaging.
1009	   */
1010	  async #runProfile() {
1011	    if (this.profileRunning) return;
1012	
1013	    const profiler = window.__mermaidProfiler;
1014	    if (!profiler) {
1015	      this.profileError =
1016	        'Profiling is not available in this build. Restart the dev server (`pnpm dev`) — it compiles mermaid with profiling enabled.';
1017	      return;
1018	    }
1019	    const m = (await window.mermaidReady?.catch(() => undefined)) ?? window.mermaid;
1020	    if (!m) {
1021	      this.profileError = 'window.mermaid is not available.';
1022	      return;
1023	    }
1024	
1025	    const layouts = this.profileLayouts.length ? this.profileLayouts : [this.layout];
1026	    const iterations = Math.max(1, Math.min(50, Math.round(this.profileIterations) || 1));
1027	
1028	    this.profileError = '';
1029	    this.profileResults = null;
1030	    this.profileRunning = true;
1031	    this.#profileCancel = false;
1032	
1033	    const diagrams = await this.#resolveProfileDiagrams();
1034	    if (diagrams.length === 0) {
1035	      this.profileError = 'No diagrams to profile.';
1036	      this.profileRunning = false;
1037	      return;
1038	    }
1039	
1040	    const prevEnabled = profiler.enabled;
1041	    const prevAutoPrint = profiler.autoPrint;
1042	    profiler.enable();
1043	    // Suppress the per-render console summary during a batch; we render our own table.
1044	    profiler.autoPrint = false;
1045	
1046	    const results: LayoutSetResult[] = [];
1047	
1048	    try {
1049	      // Warmup: load each layout module + JIT once, untimed and discarded, so the
1050	      // one-time dynamic import doesn't inflate the first measured render.
1051	      this.profileProgress = 'warming up…';
1052	      await this.updateComplete;
1053	      for (const layout of layouts) {
1054	        try {
1055	          await m.initialize(this.#profileInitConfig(layout));
1056	          await m.render(`dev-profile-warmup-${layout}`, diagrams[0].source);
1057	        } catch {
1058	          // A layout that can't render the first diagram is reported per-run below.
1059	        }
1060	      }
1061	
1062	      const totalUnits = layouts.length * diagrams.length;
1063	      let unit = 0;
1064	      for (const layout of layouts) {
1065	        const perDiagram: DiagramResult[] = [];
1066	        for (const diagram of diagrams) {
1067	          if (this.#profileCancel) break;
1068	          unit++;
1069	          await m.initialize(this.#profileInitConfig(layout));
1070	          profiler.clear();
1071	          let failures = 0;
1072	          for (let i = 0; i < iterations; i++) {
1073	            if (this.#profileCancel) break;
1074	            this.profileProgress = `${layout} · ${baseName(diagram.path)} · ${i + 1}/${iterations} (${unit}/${totalUnits})`;
1075	            // Let Lit flush the progress label before the (potentially long) render.
1076	            await this.updateComplete;
1077	            profiler.runLabel = layout;
1078	            const id = `dev-profile-${unit}-${i}-${Math.random().toString(16).slice(2)}`;
1079	            try {
1080	              await m.render(id, diagram.source);
1081	            } catch (e) {
1082	              failures++;
1083	              console.error(
1084	                `[dev-explorer] profile render failed for layout=${layout} ${diagram.path}:`,
1085	                e
1086	              );
1087	            }
1088	          }
1089	          const samples = profiler.records.map((r) => sampleFromTree(r.tree, r.buckets));
1090	          perDiagram.push({ diagram: diagram.path, stats: trimmedStats(samples), failures });
1091	        }
1092	
1093	        const measured = perDiagram.filter((d) => d.stats);
1094	        const phaseTotals: Record<string, number> = {};
1095	        const phaseKeys = new Set<string>();
1096	        for (const d of measured) {
1097	          for (const k of Object.keys(d.stats?.phases ?? {})) phaseKeys.add(k);
1098	        }
1099	        for (const phase of phaseKeys) {
1100	          phaseTotals[phase] = measured.reduce((s, d) => s + (d.stats?.phases[phase] ?? 0), 0);
1101	        }
1102	        results.push({
1103	          layout,
1104	          perDiagram,
1105	          score: measured.reduce((s, d) => s + (d.stats?.total ?? 0), 0),
1106	          phaseTotals,
1107	          failures: perDiagram.reduce((s, d) => s + d.failures, 0),
1108	        });
1109	        if (this.#profileCancel) break;
1110	      }
1111	
1112	      this.profileResults = results;
1113	    } catch (e) {
1114	      this.profileError = e instanceof Error ? e.message : String(e);
1115	    } finally {
1116	      profiler.autoPrint = prevAutoPrint;
1117	      if (!prevEnabled) profiler.disable();
1118	      this.profileRunning = false;
1119	      this.profileProgress = '';
1120	    }
