1629	          </tr>
1630	        </thead>
1631	        <tbody>
1632	          ${PROFILE_PHASES.flatMap((phase) => {
1633	            const row = html`
1634	              <tr>
1635	                <th class="phase">${phase}</th>
1636	                ${results.map((r) => html`<td>${fmtMs(r.phaseTotals[phase])}</td>`)}
1637	              </tr>
1638	            `;
1639	            const subRow = (label: string, key: string) => html`
1640	              <tr class="sub-row">
1641	                <th class="phase">${label}</th>
1642	                ${results.map((r) => {
1643	                  const v = r.phaseTotals[key];
1644	                  return html`<td>${v > 0 ? fmtMs(v) : '–'}</td>`;
1645	                })}
1646	              </tr>
1647	            `;
1648	            // Break "layout" into the external library call vs. our wrapper, and
1649	            // "measure" into the DOM reflow queries (getBBox / getBoundingClientRect).
1650	            if (phase === 'layout') {
1651	              return [
1652	                row,
1653	                subRow('↳ lib (external)', 'layoutLib'),
1654	                subRow('↳ ours (wrapper)', 'layoutOurs'),
1655	              ];
1656	            }
1657	            if (phase === 'measure') {
1658	              return [
1659	                row,
1660	                subRow('↳ getBBox', 'getBBox'),
1661	                subRow('↳ getBoundingClientRect', 'getBoundingClientRect'),
1662	              ];
1663	            }
1664	            return [row];
1665	          })}
1666	          <tr class="total">
1667	            <th class="phase">score</th>
1668	            ${results.map((r) => {
1669	              const isBest = Number.isFinite(r.score) && r.score === bestScore;
1670	              return html`<td class=${isBest ? 'best' : ''}>${fmtMs(r.score)}</td>`;
1671	            })}
1672	          </tr>
1673	        </tbody>
1674	      </table>
1675	
1676	      ${multi
1677	        ? html`
1678	            <div class="profile-meta">per-diagram total (ms)</div>
1679	            <table class="profile-table">
1680	              <thead>
1681	                <tr>
1682	                  <th class="phase">diagram</th>
1683	                  ${results.map((r) => html`<th>${r.layout}</th>`)}
1684	                </tr>
1685	              </thead>
1686	              <tbody>
1687	                ${diagrams.map((d, di) => {
1688	                  const rowVals = results
1689	                    .map((r) => r.perDiagram[di]?.stats?.total)
1690	                    .filter((v): v is number => typeof v === 'number');
1691	                  const bestVal = rowVals.length ? Math.min(...rowVals) : NaN;
1692	                  return html`
1693	                    <tr>
1694	                      <th class="phase">${baseName(d.diagram)}</th>
1695	                      ${results.map((r) => {
1696	                        const dr = r.perDiagram[di];
1697	                        const v = dr?.stats?.total;
1698	                        const isBest = typeof v === 'number' && v === bestVal;
1699	                        return html`<td class=${isBest ? 'best' : ''}>
1700	                          ${dr?.stats
1701	                            ? fmtMs(v!)
1702	                            : dr?.failures
1703	                              ? html`<span class="profile-fail">fail</span>`
1704	                              : '–'}
1705	                        </td>`;
1706	                      })}
1707	                    </tr>
1708	                  `;
1709	                })}
1710	              </tbody>
1711	            </table>
1712	          `
1713	        : nothing}
1714	    `;
1715	  }
1716	}
1717	
1718	customElements.define('dev-diagram-viewer', DevDiagramViewer);
