109	  // Batch appends into ONE state update per frame. The old code reassigned
110	  // `this.logs` on every entry, so a render emitting N log lines triggered N
111	  // Lit re-renders, each re-formatting up to N entries → O(n²) and seconds of
112	  // wasted reformatting (the dagre-vs-elk "spinning" was entirely this).
113	  // Coalescing collapses a whole render's logs into a single bounded update.
114	  append(entry: LogEntry) {
115	    this.#pending.push(entry);
116	    if (this.#flushHandle) {
