141	    textarea.value = text;
142	    textarea.setAttribute('readonly', '');
143	    textarea.style.position = 'fixed';
144	    textarea.style.top = '0';
145	    textarea.style.left = '0';
146	    textarea.style.opacity = '0';
147	    document.body.appendChild(textarea);
148	    textarea.select();
149	    textarea.setSelectionRange(0, textarea.value.length);
150	    try {
151	      return document.execCommand('copy');
152	    } finally {
153	      document.body.removeChild(textarea);
154	    }
155	  }
