157	  async copyVisible() {
158	    const text = this.#visibleText();
159	    if (!text) return;
160	
161	    try {
162	      const clipboard = globalThis.navigator?.clipboard;
163	      if (clipboard && typeof clipboard.writeText === 'function') {
164	        await clipboard.writeText(text);
